/* rules_v3 port - Web MVP calculation core
 *
 * This file is a line-for-line port of prototype/rules_v3.py. It is NOT a re-implementation
 * of the business rules: every number comes from window.RULEPACK (generated by
 * tools/build_rule_pack_v4.py), and tools/check_python_web_parity.py runs both cores over
 * the same cases and compares the complete structured output with a 1e-9 tolerance. A
 * mismatch blocks delivery.
 *
 * Owner decisions encoded (see rules_v3.py for the authoritative wording):
 *   DEC-01 tie -> RANGE, recommended_sku null, preferred NOT_ESTABLISHED, price every member
 *   DEC-02 Panel = Panel Spec Count; D2:H2 comments excluded
 *   DEC-04 explicit wave only; 未特别指定 = NO_EXPLICIT_ASSIGNMENT, never UNKNOWN
 *   DEC-05 Quantity Model per cell, no pseudo rates
 *   DEC-06 only a proven ADDITIONAL_CONFIRMED_REUSE deducts
 *   DEC-09 Certification is one model; FVT and SIT each read their own row; a range may
 *          only come from the SKU answer (SKU_NOT_ESTABLISHED).
 *   DEC-10 the ADOPTED Certification quantity is the Appendix total for that Function,
 *          Phase and SKU count, counted exactly once. The Main Table per-SKU quantity and its
 *          derived total stay on the record as audit evidence (counted 0 times) and are never
 *          added to the adopted value. J33 stays BREAKDOWN_EVIDENCE and is never added.
 *   D-01   no business rounding; 1e-9 comparison tolerance; display never writes back
 */
(function (global) {
  "use strict";

  var P = global.RULEPACK;
  if (!P) { throw new Error("rulepack.js must be loaded before core.js"); }

  var ENGINE_NAME = "rules_v3_web";
  var ENGINE_VERSION = "4.0";
  var TOL = 1e-9;
  var SKU_RANGE = P.sku_range;
  var PHASES = P.phases;
  var DIMS = P.dims;
  var DIM_WEIGHT = P.dim_weight;
  var VERDICT_WEIGHT = P.verdict_weight;
  var MATCH = "MATCH", PARTIAL = "PARTIAL_MATCH", MISM = "MISMATCH", UNKNOWN = "UNKNOWN";
  var WAVE_CURRENT = "CURRENT_WAVE", WAVE_LATER = "LATER_WAVE", WAVE_UNKNOWN = "UNKNOWN";
  var WAVE_NONE = "NO_EXPLICIT_ASSIGNMENT";
  var REUSE_EMBEDDED = "ALREADY_EMBEDDED_IN_BASELINE";
  var REUSE_ADDITIONAL = "ADDITIONAL_CONFIRMED_REUSE";
  var REUSE_POTENTIAL = "POTENTIAL_REUSE";
  var PRIMARY = "PRIMARY_QUANTITY_MODEL";
  var VALIDATION = "DERIVED_TOTAL_VALIDATION";    // Phase 3a wording, kept in the enum
  var BREAKDOWN = "BREAKDOWN_EVIDENCE";
  var ADOPTED = "ADOPTED_ABSOLUTE_TOTAL";         // DEC-10: the adopted Appendix total
  var AUDIT = "DERIVED_MAIN_TABLE_AUDIT";         // DEC-10: retained Main Table check
  var ADOPTED_SOURCE = "APPENDIX_TABLE_TOTAL";
  var VERIFIED = "VERIFIED", MISMATCH_CELL = "MISMATCH";
  var RANGE_REASON_SKU = "SKU_NOT_ESTABLISHED";
  var MAX_WAVE_COMBOS = 32;

  var QCELL = {}, FUNCS = [], FUNCS_CATEGORY = {}, EMBEDDED = P.baseline_embedded_sharing;
  for (var i = 0; i < P.cells.length; i++) {
    QCELL[P.cells[i].function_id + "|" + P.cells[i].phase] = P.cells[i];
  }
  for (var j = 0; j < P.functions.length; j++) {
    FUNCS.push(P.functions[j]);
    FUNCS_CATEGORY[P.functions[j].function_id] = P.functions[j].category;
  }
  var UNRESOLVED_COMMENTS = P.sku_definition_header_comments || {};

  /* ---------------- primitives ---------------- */

  function approx(a, b, tol) {
    if (tol === undefined) { tol = TOL; }
    if (a === null || a === undefined || b === null || b === undefined) { return a === b; }
    return Math.abs(Number(a) - Number(b)) <= tol;
  }
  function skuKey(n) { return "SKU" + n; }
  function round(v, n) {                  // only ever used for display-side scores
    var p = Math.pow(10, n); return Math.round((v + Number.EPSILON) * p) / p;
  }
  function sum(arr) {
    // Neumaier compensated summation - the same algorithm CPython's built-in sum()
    // uses for floats since 3.12. Using a plain += loop here changes the last bits
    // (e.g. 196.5 becomes 196.50000000000003), and the two cores must agree exactly.
    var x = 0.0, c = 0.0;
    for (var k = 0; k < arr.length; k++) {
      var y = Number(arr[k]);
      var t = x + y;
      if (Math.abs(x) > Math.abs(y)) { c += (x - t) + y; } else { c += (y - t) + x; }
      x = t;
    }
    return x + c;
  }

  /* ---------------- input model ---------------- */

  function Spec(label, wave, waveSource) {
    this.label = label || "";
    this.wave = wave || WAVE_CURRENT;
    this.wave_source = waveSource || "NOT_PROVIDED";
  }

  function KeyFactor(name, fileValue, userValue, userEdited) {
    this.name = name;
    this.file_value = (fileValue === undefined ? null : fileValue);
    this.user_value = (userValue === undefined ? null : userValue);
    this.user_edited = !!userEdited;
    this.specs = [];
  }
  KeyFactor.prototype.effective = function () {
    if (this.user_edited) { return this.user_value; }
    if (this.file_value !== null && this.file_value !== undefined) { return this.file_value; }
    return this.user_value;
  };
  KeyFactor.prototype.source = function () {
    if (this.user_edited) { return "USER"; }
    if (this.file_value !== null && this.file_value !== undefined) { return "FILE"; }
    if (this.user_value !== null && this.user_value !== undefined) { return "USER"; }
    return "UNKNOWN";
  };
  KeyFactor.prototype.statusUser = function () {
    return this.effective() === null ? "请补充" : "";
  };
  KeyFactor.prototype.normaliseSpecs = function () {
    var n = this.effective();
    if (n === null || n === undefined) { this.specs = []; return; }
    if (this.specs.length !== n) {
      this.specs = [];
      for (var i = 0; i < n; i++) { this.specs.push(new Spec(this.name + (i + 1), WAVE_CURRENT, "NOT_PROVIDED")); }
    }
    for (var s = 0; s < this.specs.length; s++) {
      var sp = this.specs[s];
      if (sp.wave === WAVE_NONE) { sp.wave = WAVE_CURRENT; sp.wave_source = "NOT_PROVIDED"; }
      else if (sp.wave !== WAVE_CURRENT && sp.wave !== WAVE_LATER && sp.wave !== WAVE_UNKNOWN) {
        sp.wave = WAVE_CURRENT; sp.wave_source = "NOT_PROVIDED";
      }
    }
    if (n === 1) {
      this.specs[0].wave = WAVE_CURRENT;
      if (this.specs[0].wave_source === "NOT_PROVIDED") { this.specs[0].wave_source = "IMPLICIT_SINGLE_SPEC"; }
    }
  };
  KeyFactor.prototype.waveReport = function () {
    var n = this.effective() || 0, cur = 0, later = 0, unk = 0, untagged = 0, excluded = [];
    for (var i = 0; i < this.specs.length; i++) {
      var s = this.specs[i];
      if (s.wave === WAVE_CURRENT) { cur++; }
      if (s.wave === WAVE_LATER) { later++; excluded.push(s.label); }
      if (s.wave === WAVE_UNKNOWN) { unk++; }
      if (s.wave_source === "NOT_PROVIDED" || s.wave_source === "IMPLICIT_SINGLE_SPEC") { untagged++; }
    }
    var state;
    if (n === 0) { state = "NOT_APPLICABLE"; }
    else if (unk) { state = WAVE_UNKNOWN; }
    else if (later) { state = "ASSIGNED"; }
    else if (untagged && n >= 2) { state = "NOT_PROVIDED"; }
    else { state = "ALL_CURRENT"; }
    var srcs = {};
    for (var k = 0; k < this.specs.length; k++) { srcs[this.specs[k].wave_source] = 1; }
    var sources = Object.keys(srcs).sort();
    return { factor: this.name, count: n, current: cur, later: later, unknown: unk,
             untagged: untagged, wave_state: state, excluded_from_current_wave: excluded,
             sources: sources };
  };
  KeyFactor.prototype.unknownCombinations = function () {
    var base = 0, unk = 0;
    for (var i = 0; i < this.specs.length; i++) {
      if (this.specs[i].wave === WAVE_CURRENT) { base++; }
      if (this.specs[i].wave === WAVE_UNKNOWN) { unk++; }
    }
    if (!this.specs.length) { return []; }
    var raw = [];
    for (var k = 0; k <= unk; k++) { raw.push(base + k); }
    if (base === 0 && unk) { raw = raw.map(function (v) { return Math.max(1, v); }); }
    var seen = {}, out = [];
    for (var m = 0; m < raw.length; m++) { if (!seen[raw[m]]) { seen[raw[m]] = 1; out.push(raw[m]); } }
    return out.sort(function (a, b) { return a - b; });
  };

  function AnalysisInput() {
    var f = {};
    for (var i = 0; i < DIMS.length; i++) { f[DIMS[i]] = new KeyFactor(DIMS[i]); }
    this.cpu = f.cpu; this.gpu = f.gpu; this.panel = f.panel; this.ssd = f.ssd; this.mem = f.mem;
    this.odm = null; this.project_name = null; this.project_type = "CLEAN_SHEET";
    this.phase_scope = ["FVT", "SIT"];
    this.reuse_items = []; this.potential_reuse = 0.0; this.risk_reserve_pct = null;
    this.certification_override = null; this.extra_demand = [];
  }
  AnalysisInput.prototype.factors = function () {
    var o = {}; for (var i = 0; i < DIMS.length; i++) { o[DIMS[i]] = this[DIMS[i]]; } return o;
  };
  AnalysisInput.prototype.missing = function () {
    var f = this.factors(), out = [];
    for (var i = 0; i < DIMS.length; i++) { if (f[DIMS[i]].effective() === null) { out.push(DIMS[i]); } }
    return out;
  };
  AnalysisInput.prototype.normalise = function () {
    if (this.phase_scope && this.phase_scope.length) {
      var keep = [];
      for (var p = 0; p < PHASES.length; p++) {
        if (this.phase_scope.indexOf(PHASES[p]) >= 0) { keep.push(PHASES[p]); }
      }
      this.phase_scope = keep.length ? keep : PHASES.slice();
    } else { this.phase_scope = PHASES.slice(); }
    var f = this.factors();
    for (var i = 0; i < DIMS.length; i++) { f[DIMS[i]].normaliseSpecs(); }
    return this;
  };

  AnalysisInput.fromDocument = function (doc) {
    doc = doc || {};
    var kf = doc.key_factors || {};
    var wa = doc.wave_assignment || {};
    var waves = wa.specs || [];
    var declaredBy = wa.declared_by || "NOT_PROVIDED";
    var a = new AnalysisInput();
    for (var d = 0; d < DIMS.length; d++) {
      var name = DIMS[d], dd = kf[name] || {};
      var n = dd.effective;
      if (n === null || n === undefined) {
        n = dd.user_edited ? dd.user_value : dd.file_value;
        if (n === null || n === undefined) { n = dd.user_value; }
      }
      var fac = new KeyFactor(name, dd.file_value === undefined ? null : dd.file_value,
                              dd.user_value === undefined ? null : dd.user_value,
                              !!dd.user_edited);
      if (n) {
        for (var s = 0; s < n; s++) { fac.specs.push(new Spec(name + (s + 1), WAVE_CURRENT, "NOT_PROVIDED")); }
        for (var w = 0; w < waves.length; w++) {
          var wv = waves[w];
          if (wv.factor !== name) { continue; }
          var idx = (wv.spec_index === undefined ? 1 : wv.spec_index) - 1;
          if (idx < 0 || idx >= n) { continue; }
          // 未特别指定 arrives as NO_EXPLICIT_ASSIGNMENT: current wave, nobody said
          // otherwise. It is never UNKNOWN - UNKNOWN fans the answer out into several
          // scenarios, which is not what the user asked for.
          if (wv.wave === WAVE_NONE) {
            fac.specs[idx].wave = WAVE_CURRENT; fac.specs[idx].wave_source = "NOT_PROVIDED";
          } else {
            fac.specs[idx].wave = wv.wave || WAVE_CURRENT;
            fac.specs[idx].wave_source = wv.wave_source || declaredBy;
          }
          if (wv.spec_label) { fac.specs[idx].label = wv.spec_label; }
        }
      }
      a[name] = fac;
    }
    var cert = doc.certification_input || {};
    var ovr = null, ovList = cert.overrides || [];
    for (var o = 0; o < ovList.length; o++) {
      ovr = ovr || {};
      ovr[ovList[o].function_id] = ovr[ovList[o].function_id] || {};
      ovr[ovList[o].function_id][ovList[o].phase] = Number(ovList[o].qty);
    }
    var rr = doc.risk_reserve || {};
    a.odm = doc.odm === undefined ? null : doc.odm;
    a.project_name = doc.project_name === undefined ? null : doc.project_name;
    a.project_type = doc.project_type || "CLEAN_SHEET";
    a.phase_scope = doc.phase_scope ? doc.phase_scope.slice() : PHASES.slice();
    a.reuse_items = (doc.reuse_items || []).map(function (r) {
      return { qty: Number(r.qty === undefined ? 0 : r.qty),
               reuse_status: r.reuse_status || "UNKNOWN_OVERLAP",
               unit: r.unit || "UNIT",
               function_id: r.function_id === undefined ? null : r.function_id,
               basis: r.basis || "", proven_not_in_baseline: !!r.proven_not_in_baseline,
               note: r.note || "" };
    });
    a.potential_reuse = Number(doc.potential_reuse_display_only || 0);
    a.risk_reserve_pct = (rr.percent === null || rr.percent === undefined) ? 0.0 : Number(rr.percent);
    a.certification_override = (ovr && Object.keys(ovr).length) ? ovr : null;
    a.extra_demand = (doc.additional_demand || []).slice();
    return a;
  };

  /* ---------------- wave scenarios ---------------- */

  function countsKey(c) {
    var parts = [];
    for (var i = 0; i < DIMS.length; i++) {
      parts.push(DIMS[i] + "=" + (c[DIMS[i]] === null || c[DIMS[i]] === undefined ? "x" : c[DIMS[i]]));
    }
    return parts.join("&");
  }

  function waveScenarios(inp) {
    var fac = inp.factors(), all = {};
    for (var i = 0; i < DIMS.length; i++) { all[DIMS[i]] = fac[DIMS[i]].effective(); }
    var out = [{ scope: "FULL_PROJECT", counts: all, wave_basis: "ALL_SPECS" }];

    var fanKeys = [], fanVals = [], unknownFactors = [], untaggedFactors = [];
    for (var d = 0; d < DIMS.length; d++) {
      var name = DIMS[d], f = fac[name];
      if (f.effective() === null) { continue; }
      var rep = f.waveReport();
      fanKeys.push(name);
      if (rep.wave_state === WAVE_UNKNOWN) {
        unknownFactors.push(name);
        fanVals.push(f.unknownCombinations());
      } else {
        if (rep.wave_state === "NOT_PROVIDED") { untaggedFactors.push(name); }
        var cur = 0;
        for (var s = 0; s < f.specs.length; s++) { if (f.specs[s].wave === WAVE_CURRENT) { cur++; } }
        fanVals.push([cur]);
      }
    }
    var combos = [ [] ];
    for (var k = 0; k < fanVals.length; k++) {
      var next = [];
      for (var c = 0; c < combos.length; c++) {
        for (var v = 0; v < fanVals[k].length; v++) { next.push(combos[c].concat([fanVals[k][v]])); }
      }
      combos = next;
    }
    var truncated = combos.length > MAX_WAVE_COMBOS;
    if (truncated) { combos = [combos[0], combos[combos.length - 1]]; }

    var declaredAny = false;
    for (var q = 0; q < DIMS.length; q++) {
      var sp2 = fac[DIMS[q]].specs;
      for (var z = 0; z < sp2.length; z++) {
        if (sp2[z].wave_source === "FORMAL_REQUIREMENT_SHEET" || sp2[z].wave_source === "USER_SELECTED") { declaredAny = true; }
      }
    }

    for (var ci = 0; ci < combos.length; ci++) {
      var merged = {};
      for (var m = 0; m < DIMS.length; m++) { merged[DIMS[m]] = fac[DIMS[m]].effective(); }
      for (var w2 = 0; w2 < fanKeys.length; w2++) { merged[fanKeys[w2]] = combos[ci][w2]; }
      var excluded = [];
      for (var e = 0; e < DIMS.length; e++) {
        var specs = fac[DIMS[e]].specs;
        for (var e2 = 0; e2 < specs.length; e2++) {
          if (specs[e2].wave === WAVE_LATER) { excluded.push({ factor: DIMS[e], label: specs[e2].label }); }
        }
      }
      out.push({ scope: "CURRENT_WAVE", counts: merged,
                 wave_basis: unknownFactors.length ? "UNKNOWN_FANOUT"
                           : (declaredAny ? "EXPLICIT_ASSIGNMENT" : "NO_EXPLICIT_ASSIGNMENT"),
                 unknown_factors: unknownFactors.slice(),
                 untagged_factors: untaggedFactors.slice(),
                 excluded_specs: excluded, truncated: truncated });
    }

    var seen = {}, uniq = [];
    for (var u = 0; u < out.length; u++) {
      var key = out[u].scope + "|" + countsKey(out[u].counts);
      if (seen[key]) { continue; }
      seen[key] = 1; uniq.push(out[u]);
    }
    var fullKeys = {};
    for (var a1 = 0; a1 < uniq.length; a1++) {
      if (uniq[a1].scope === "FULL_PROJECT") { fullKeys[countsKey(uniq[a1].counts)] = 1; }
    }
    for (var n1 = 0; n1 < uniq.length; n1++) {
      var sc = uniq[n1], parts = [];
      for (var n2 = 0; n2 < DIMS.length; n2++) {
        parts.push(DIMS[n2] + (sc.counts[DIMS[n2]] === null || sc.counts[DIMS[n2]] === undefined ? "x" : sc.counts[DIMS[n2]]));
      }
      sc.scenario_id = sc.scope + ":" + parts.join("-");
      sc.identical_to_full_project = (sc.scope === "CURRENT_WAVE") && !!fullKeys[countsKey(sc.counts)];
    }
    return uniq;
  }

  /* ---------------- SKU recommendation ---------------- */

  function definitions() { return P.sku_definition; }

  function domainBounds() {
    var lo = {}, hi = {}, defs = definitions();
    for (var d = 0; d < DIMS.length; d++) {
      var vals = [];
      for (var s = 0; s < SKU_RANGE.length; s++) {
        var r = defs[skuKey(SKU_RANGE[s])];
        if (r && r[DIMS[d]]) { vals = vals.concat(r[DIMS[d]]); }
      }
      lo[DIMS[d]] = Math.min.apply(null, vals);
      hi[DIMS[d]] = Math.max.apply(null, vals);
    }
    return { low: lo, high: hi };
  }

  function dimVerdict(value, rng) {
    if (value === null || value === undefined || !rng) { return UNKNOWN; }
    if (rng[0] <= value && value <= rng[1]) { return MATCH; }
    if (value === rng[0] - 1 || value === rng[1] + 1) { return PARTIAL; }
    return MISM;
  }

  function outOfDomain(counts) {
    var b = domainBounds(), bad = [];
    for (var d = 0; d < DIMS.length; d++) {
      var v = counts[DIMS[d]];
      if (v === null || v === undefined) { continue; }
      if (v > b.high[DIMS[d]]) { bad.push({ dimension: DIMS[d], value: v, supported_max: b.high[DIMS[d]] }); }
      else if (v < b.low[DIMS[d]]) { bad.push({ dimension: DIMS[d], value: v, supported_min: b.low[DIMS[d]] }); }
    }
    return bad;
  }

  function matchSku(counts) {
    var defs = definitions(), detail = {}, scores = {};
    for (var i = 0; i < SKU_RANGE.length; i++) {
      var sku = SKU_RANGE[i], dd = defs[skuKey(sku)];
      if (!dd) { continue; }
      var per = {}, wsum = 0, knownW = 0;
      for (var k = 0; k < DIMS.length; k++) {
        var dim = DIMS[k], vv = dimVerdict(counts[dim], dd[dim]);
        per[dim] = { verdict: vv, range: dd[dim] ? [dd[dim][0], dd[dim][1]] : null,
                     weight: DIM_WEIGHT[dim] };
        wsum += VERDICT_WEIGHT[vv] * DIM_WEIGHT[dim];
        if (counts[dim] !== null && counts[dim] !== undefined) { knownW += DIM_WEIGHT[dim]; }
      }
      scores[sku] = knownW ? round(wsum / knownW, 6) : 0.0;
      detail[sku] = per;
    }
    var known = [], missing = [];
    for (var q = 0; q < DIMS.length; q++) {
      if (counts[DIMS[q]] !== null && counts[DIMS[q]] !== undefined) { known.push(DIMS[q]); }
      else { missing.push(DIMS[q]); }
    }
    if (!known.length) {
      return { state: "UNDETERMINED", recommended_sku: null, preferred_sku: "NOT_ESTABLISHED",
               sku_range: null, scores: scores, dimension_detail: detail,
               reasons: ["no key factor supplied - nothing can be recommended"], out_of_domain: [] };
    }
    var bad = outOfDomain(counts);
    if (bad.length) {
      var rs = bad.map(function (b) {
        return b.dimension + "=" + b.value + " is outside the supported SKU Definition domain " +
               "(max " + b.supported_max + ") - no rule exists yet, see ORI-13";
      });
      return { state: "OUT_OF_DOMAIN", recommended_sku: null, preferred_sku: "NOT_ESTABLISHED",
               sku_range: null, scores: scores, dimension_detail: detail, out_of_domain: bad,
               reasons: rs };
    }
    var best = -Infinity;
    for (var s2 in scores) { if (scores[s2] > best) { best = scores[s2]; } }
    var tied = [];
    for (var s3 in scores) { if (approx(scores[s3], best)) { tied.push(Number(s3)); } }
    tied.sort(function (a, b) { return a - b; });

    var state, rec, rng, reasons;
    if (tied.length > 1) {
      state = "RANGE"; rec = null; rng = [tied[0], tied[tied.length - 1]];
      reasons = ["SKU " + tied.join(", ") + " are indistinguishable on the available "
                 + "evidence (score " + best.toFixed(6) + ")"];
      if (missing.length) { reasons.push("unanswered key factor(s): " + missing.join(", ")); }
      reasons.push("DEC-01: the tie is reported as a range, no weighting is used to force a single answer");
    } else if (known.length < DIMS.length) {
      state = "SINGLE_WITH_RESERVATION"; rec = tied[0]; rng = [tied[0], tied[0]];
      reasons = ["best supported answer is " + tied[0] + " SKU on the answered dimensions",
                 "unanswered key factor(s): " + missing.join(", ")];
    } else {
      state = "SINGLE"; rec = tied[0]; rng = [tied[0], tied[0]];
      reasons = ["every answered dimension supports " + tied[0] + " SKU"];
      var partials = [];
      for (var p = 0; p < DIMS.length; p++) {
        if (detail[tied[0]][DIMS[p]].verdict === PARTIAL) { partials.push(DIMS[p]); }
      }
      if (partials.length) {
        state = "SINGLE_WITH_RESERVATION";
        reasons.push("dimension(s) one step outside the definition: " + partials.join(", "));
      }
    }
    var neighbours = {};
    for (var s4 = 0; s4 < SKU_RANGE.length; s4++) {
      if (tied.indexOf(SKU_RANGE[s4]) < 0) { neighbours[SKU_RANGE[s4]] = scores[SKU_RANGE[s4]]; }
    }
    return { state: state, recommended_sku: rec,
             preferred_sku: (rec !== null ? rec : "NOT_ESTABLISHED"), sku_range: rng,
             tie_set: tied, scores: scores, dimension_detail: detail,
             neighbour_scores: neighbours, reasons: reasons, out_of_domain: [] };
  }

  function candidatesToPrice(match) {
    if (match.state === "UNDETERMINED" || match.state === "OUT_OF_DOMAIN") { return []; }
    if (match.state === "RANGE") {
      var out = [], tie = match.tie_set || [];
      for (var s = match.sku_range[0]; s <= match.sku_range[1]; s++) {
        if (tie.indexOf(s) >= 0) { out.push(s); }
      }
      return out;
    }
    return [match.recommended_sku];
  }

  /* ---------------- demand ---------------- */

  function phasesFor(inp) { return (inp.phase_scope && inp.phase_scope.length) ? inp.phase_scope : PHASES; }

  function certCellAudit(fid, phase, sku) {
    var c = QCELL[fid + "|" + phase];
    var v = (c.audit && c.audit.per_sku) ? c.audit.per_sku[skuKey(sku)] : null;
    if (!v) { return { role: null, verification_status: null }; }
    return { role: AUDIT, adopted_value: v.appendix_total,
             adopted_value_source: ADOPTED_SOURCE,
             appendix_label: v.appendix_label, appendix_total: v.appendix_total,
             appendix_row: v.appendix_row, main_table_row: v.main_table_row,
             main_table_per_sku_quantity: v.main_table_per_sku_quantity,
             derived_total: v.derived_total, delta: v.delta,
             verification_status: v.verification_status,
             counted_in_project_total: false,
             may_be_added_to_the_adopted_value: false,
             relationship: "main_table_per_sku_quantity x sku_count == appendix_total" };
  }

  function cellValue(fid, phase, sku) {
    var c = QCELL[fid + "|" + phase];
    var isCert = !!c.audit && FUNCS_CATEGORY[fid] === "CERT";
    if (c.quantity_model === "UNRESOLVED") {
      return { quantity_model: c.quantity_model, value: null, candidates: {},
               unevaluable_sources: [], owner_review_required: true,
               adopted_source: "NONE_UNRESOLVED", rule_id: c.rule_id,
               adopted_value_evidence_role: null,
               main_table_per_sku_quantity: null, main_derived_total: null,
               audit: null, breakdown_evidence: null };
    }
    return { quantity_model: c.quantity_model, value: Number(c.adopted_absolute[skuKey(sku)]),
             candidates: {}, unevaluable_sources: [],
             owner_review_required: c.owner_review_required, adopted_source: c.adopted_source,
             rule_id: c.rule_id,
             adopted_value_evidence_role: c.adopted_value_evidence_role || PRIMARY,
             main_table_per_sku_quantity: isCert ? c.main_table_per_sku_quantity[skuKey(sku)] : null,
             main_derived_total: (isCert && c.main_table_absolute[skuKey(sku)] !== null
                                  ? c.main_table_absolute[skuKey(sku)] : null),
             audit: isCert ? certCellAudit(fid, phase, sku) : null,
             breakdown_evidence: c.breakdown_evidence || null };
  }

  function demandRows(inp, sku) {
    var rows = [], ph = phasesFor(inp);
    for (var f = 0; f < FUNCS.length; f++) {
      var fid = FUNCS[f].function_id;
      for (var p = 0; p < ph.length; p++) {
        var phase = ph[p], cell = cellValue(fid, phase, sku);
        var override = null;
        if (inp.certification_override && inp.certification_override[fid]) {
          var ov = inp.certification_override[fid][phase];
          if (ov !== null && ov !== undefined) { override = ov; }
        }
        var value = cell.value, src = cell.adopted_source, system = value;
        var mainDerived = cell.main_derived_total;
        if (override !== null) { value = Number(override); src = "USER_MANUAL_OVERRIDE"; }
        var verif = cell.audit;
        if (override !== null && verif) {
          verif = JSON.parse(JSON.stringify(verif));
          verif.user_override_vs_adopted = (verif.adopted_value === null || verif.adopted_value === undefined)
            ? "NOT_COMPARED"
            : (approx(value, verif.adopted_value)
               ? "MATCHES_ADOPTED_APPENDIX_VALUE" : "DOES_NOT_MATCH_ADOPTED_APPENDIX_VALUE");
        }
        rows.push({ function_id: fid, function_name: FUNCS[f].name, category: FUNCS[f].category,
                    phase: phase, sku_qty: sku, quantity_model: cell.quantity_model,
                    evidence_role: cell.adopted_value_evidence_role || PRIMARY,
                    base_demand: value, system_computed_value: system,
                    user_input_value: (override !== null ? Number(override) : null),
                    value_source: src,
                    main_table_per_sku_quantity: cell.main_table_per_sku_quantity,
                    main_table_derived_total: mainDerived,
                    candidate_values: cell.candidates, models_not_evaluable: cell.unevaluable_sources,
                    unit: "UNIT",
                    owner_review_required: cell.owner_review_required && (override === null),
                    main_table_audit: verif,
                    breakdown_evidence_role: cell.breakdown_evidence ? BREAKDOWN : null,
                    is_temporary_model: cell.quantity_model === "PER_PHASE_FIXED",
                    override_scope: (override !== null ? "THIS_ANALYSIS_ONLY" : null),
                    rule_id: cell.rule_id,
                    evidence: { source_file: P.source_file.file, sheet: P.source_file.sheet,
                                row: FUNCS[f].source_rows[phase.toLowerCase()] } });
      }
    }
    return rows;
  }

  /* ---------------- Certification (DEC-09) ---------------- */

  function certificationResult(rows) {
    var cert = rows.filter(function (r) { return r.category === "CERT"; });
    if (!cert.length) { return { present: false }; }
    var sku = cert[0].sku_qty;
    var fvt = sum(cert.filter(function (r) { return r.phase === "FVT"; })
                 .map(function (r) { return r.base_demand; }));
    var sit = sum(cert.filter(function (r) { return r.phase === "SIT"; })
                  .map(function (r) { return r.base_demand; }));
    var cellsOut = [], statuses = [], overridden = false;
    for (var i = 0; i < cert.length; i++) {
      var r = cert[i], v = r.main_table_audit || {};
      statuses.push(v.verification_status);
      if (r.value_source === "USER_MANUAL_OVERRIDE") { overridden = true; }
      cellsOut.push({ function_id: r.function_id, function_name: r.function_name, phase: r.phase,
                      sku_count: r.sku_qty,
                      adopted_total: r.base_demand,
                      adopted_value_source: r.value_source,
                      applied_total: r.base_demand, user_input_total: r.user_input_value,
                      value_source: r.value_source,
                      main_table_per_sku_quantity: r.main_table_per_sku_quantity,
                      main_table_derived_total: r.main_table_derived_total,
                      appendix_total: v.appendix_total,
                      delta_appendix_minus_main_derived: v.delta,
                      delta: v.delta,
                      verification_status: v.verification_status,
                      main_derived_counted_in_project_total: false,
                      user_override_vs_adopted_value: (v.user_override_vs_adopted === undefined
                                                       ? null : v.user_override_vs_adopted),
                      override_scope: (r.value_source === "USER_MANUAL_OVERRIDE"
                                       ? "THIS_ANALYSIS_ONLY" : null),
                      main_table_row: v.main_table_row, appendix_row: v.appendix_row });
    }
    var nv = statuses.filter(function (s) { return s === VERIFIED; }).length;
    var nm = statuses.filter(function (s) { return s === MISMATCH_CELL; }).length;
    var ne = statuses.filter(function (s) { return s === "NOT_EVALUABLE"; }).length;
    var auditStatus = (nv === cellsOut.length ? "ALL_MATCHING"
                      : (nv ? "PARTIALLY_MATCHING" : "NOT_MATCHING"));
    var j33role = null, j33detail = null;
    for (var k = 0; k < cert.length; k++) {
      if (cert[k].breakdown_evidence_role) { j33role = cert[k].breakdown_evidence_role; }
      var be = (QCELL[cert[k].function_id + "|" + cert[k].phase] || {}).breakdown_evidence;
      if (be && !j33detail) { j33detail = be; }
    }
    return {
      present: true, decision: "DEC-10", model: "APPENDIX_ADOPTED_TOTAL",
      formula: "appendix_total of each Certification Function and Phase at the applied SKU " +
               "count, summed once (no per-SKU multiplication, no phase ratio)",
      applied_sku_count: sku, fvt_certification_demand: fvt, sit_certification_demand: sit,
      certification_demand_total: fvt + sit,
      recounted_from_detail: {
        FVT: sum(cellsOut.filter(function (c) { return c.phase === "FVT"; })
                 .map(function (c) { return c.adopted_total; })),
        SIT: sum(cellsOut.filter(function (c) { return c.phase === "SIT"; })
                 .map(function (c) { return c.adopted_total; })) },
      single_value: true, phase_ratio_used: null,
      counted_in_project_total_times: 1,
      adopted_value_role: ADOPTED, adopted_value_source: ADOPTED_SOURCE,
      main_table_role: AUDIT, main_derived_counted_in_project_total_times: 0,
      main_table_and_appendix_added_together: false,
      j33_role: j33role,
      j33_disposition: j33detail ? j33detail.disposition : null,
      j33_added_to_result: false, j33_counted_in_project_total_times: 0,
      j33_reference_scenario: j33detail ? j33detail.declared_reference_scenario : null,
      user_override_used: overridden, user_override_scope: "THIS_ANALYSIS_ONLY",
      main_table_audit: {
        cells_total: cellsOut.length, verified: nv, mismatch: nm, not_evaluable: ne,
        status: auditStatus, comparison_tolerance: TOL,
        counted_in_project_total_times: 0,
        note: "Main Table per-SKU quantity x SKU count versus the adopted Appendix total - " +
              "audit and difference analysis only" },
      verification: { cells_total: cellsOut.length, verified: nv, mismatch: nm,
                      not_evaluable: ne, status: auditStatus, comparison_tolerance: TOL },
      cells: cellsOut,
      mismatched_cells: cellsOut.filter(function (c) { return c.verification_status === MISMATCH_CELL; }),
      range_reason: null,
      note: "Certification is one adopted number: the Appendix total (DEC-10). The Main Table " +
            "per-SKU quantity and its derived total stay on the record for audit and " +
            "difference analysis, are counted 0 times and are never added to the adopted " +
            "value. J33 explains the RF composition and is never added."
    };
  }

  function summarise(rows) {
    var s = { FVT: 0.0, SIT: 0.0, by_category: {}, by_function: {}, unresolved_functions: {},
              excluded_unresolved: 0.0 };
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!s.by_function[r.function_name]) { s.by_function[r.function_name] = { FVT: 0.0, SIT: 0.0 }; }
      if (r.base_demand === null) { s.unresolved_functions[r.function_name] = 1; continue; }
      s[r.phase] += r.base_demand;
      s.by_function[r.function_name][r.phase] += r.base_demand;
      s.by_category[r.category] = (s.by_category[r.category] || 0.0) + r.base_demand;
    }
    s.TOTAL = s.FVT + s.SIT;
    s.unresolved_functions = Object.keys(s.unresolved_functions).sort();
    return s;
  }

  function totalsByModel(rows) {
    var unresolved = rows.filter(function (r) { return r.base_demand === null; });
    var resolved = rows.filter(function (r) { return r.base_demand !== null; });
    function total(rs) {
      return { FVT: sum(rs.filter(function (r) { return r.phase === "FVT"; })
                        .map(function (r) { return r.base_demand; })),
               SIT: sum(rs.filter(function (r) { return r.phase === "SIT"; })
                         .map(function (r) { return r.base_demand; })),
               TOTAL: sum(rs.map(function (r) { return r.base_demand; })) };
    }
    var confirmed = total(resolved);
    if (!unresolved.length) {
      var one = { model_source: "ADOPTED_MODEL", FVT: confirmed.FVT, SIT: confirmed.SIT,
                  TOTAL: confirmed.TOTAL };
      return { confirmed_only: confirmed, variants: [one], variants_not_evaluable: [],
               band: { total_min: confirmed.TOTAL, total_max: confirmed.TOTAL, spread: 0.0 },
               note: "every cell has a resolved Quantity Model - one exact total, no competing " +
                     "model and no Certification band (DEC-09)" };
    }
    var sources = [], declared = [];
    for (var i = 0; i < unresolved.length; i++) {
      for (var k in unresolved[i].candidate_values) {
        if (unresolved[i].candidate_values[k] !== null && sources.indexOf(k) < 0) { sources.push(k); }
      }
      for (var m = 0; m < (unresolved[i].models_not_evaluable || []).length; m++) {
        if (declared.indexOf(unresolved[i].models_not_evaluable[m]) < 0) { declared.push(unresolved[i].models_not_evaluable[m]); }
      }
    }
    var usable = sources.filter(function (k2) {
      return unresolved.every(function (r) { return r.candidate_values[k2] !== null && r.candidate_values[k2] !== undefined; });
    });
    var dropped = sources.filter(function (k3) { return usable.indexOf(k3) < 0; }).concat(declared);
    var variants = usable.map(function (k4) {
      var extra = unresolved.map(function (r) {
        var c = {}; for (var f2 in r) { c[f2] = r[f2]; }
        c.base_demand = Number(r.candidate_values[k4]); return c;
      });
      var t = total(resolved.concat(extra));
      t.model_source = k4; return t;
    });
    if (!variants.length) {
      var z = total(resolved); z.model_source = "ADOPTED_MODEL"; variants = [z];
      dropped.push("NO_EVALUABLE_COMPETING_MODEL");
    }
    var vals = variants.map(function (v) { return v.TOTAL; });
    return { confirmed_only: confirmed, variants: variants, variants_not_evaluable: dropped,
             band: { total_min: Math.min.apply(null, vals), total_max: Math.max.apply(null, vals),
                     spread: round(Math.max.apply(null, vals) - Math.min.apply(null, vals), 9) },
             note: "each variant is one complete demand picture under one evidence source; they " +
                   "are shown side by side and never averaged" };
  }

  /* ---------------- reuse (DEC-06) ---------------- */

  function reuseLedger(inp, rows) {
    var allowed = 0.0, items = [], oris = [];
    for (var i = 0; i < inp.reuse_items.length; i++) {
      var it = inp.reuse_items[i];
      var base = { qty: it.qty, unit: it.unit, reuse_status: it.reuse_status,
                   function_id: it.function_id, evidence_note: it.basis || it.note };
      if (it.qty === null || it.qty === undefined || it.qty < 0) {
        base.index = items.length; base.applied = 0.0;
        base.decision = "REJECTED_INVALID_QUANTITY";
        base.why = "reuse quantity must be a valid non-negative number";
        items.push(base); continue;
      }
      if (it.unit !== "UNIT") {
        base.index = items.length; base.applied = 0.0;
        base.decision = "EXCLUDED_UNIT_MISMATCH";
        base.why = "PCBA quantity must never be summed with or deducted from unit demand";
        items.push(base); continue;
      }
      var sig = (EMBEDDED[it.function_id || ""] || {}).overall;
      if (it.reuse_status === REUSE_EMBEDDED) {
        base.index = items.length; base.applied = 0.0;
        base.decision = "NOT_DEDUCTED_ALREADY_EMBEDDED";
        base.why = "the Owner states this sharing is already inside the baseline rate - " +
                   "deducting again would double count";
        items.push(base); continue;
      }
      if (it.reuse_status === REUSE_POTENTIAL) {
        base.index = items.length; base.applied = 0.0; base.decision = "DISPLAY_ONLY";
        base.why = "potential reuse is shown, never subtracted";
        items.push(base); continue;
      }
      if (it.reuse_status === "UNKNOWN_OVERLAP") {
        oris.push({ kind: "REUSE_OVERLAP_UNPROVEN", index: items.length, qty: it.qty,
                    function_id: it.function_id,
                    why: "cannot rule out double deduction, so nothing is deducted" });
        base.index = items.length; base.applied = 0.0; base.decision = "BLOCKED_UNTIL_PROVEN";
        base.why = "overlap with the baseline cannot be excluded";
        items.push(base); continue;
      }
      if (it.reuse_status !== REUSE_ADDITIONAL) {
        base.index = items.length; base.applied = 0.0; base.decision = "REJECTED_UNKNOWN_STATUS";
        base.why = it.reuse_status + " is not one of the four supported reuse states";
        items.push(base); continue;
      }
      if (!it.proven_not_in_baseline) {
        var why = "ADDITIONAL_CONFIRMED_REUSE needs proof it is not already in the baseline" +
                  (sig === "SUSPECTED" ? "; " + it.function_id + " shows an already-embedded " +
                   "sharing signal (spread/growth ~0 across SKU)" : "");
        oris.push({ kind: "REUSE_PROOF_MISSING", index: items.length, qty: it.qty,
                    function_id: it.function_id, why: why });
        base.index = items.length; base.applied = 0.0; base.decision = "BLOCKED_PROOF_MISSING";
        base.why = "proven_not_in_baseline was not asserted";
        items.push(base); continue;
      }
      allowed += Math.abs(it.qty);
      base.index = items.length; base.applied = -Math.abs(it.qty); base.decision = "DEDUCTED";
      base.why = it.basis || "user confirmed, proven and unit-denominated";
      items.push(base);
    }
    var requested = sum(inp.reuse_items.map(function (i2) { return Number(i2.qty || 0); }));
    return { deduction: -allowed, items: items, owner_review_items: oris,
             requested_reuse_quantity: requested, adopted_reuse_quantity: allowed,
             rejected_or_deferred_quantity: round(requested - allowed, 10),
             policy: "only a proven, unit-denominated ADDITIONAL_CONFIRMED_REUSE that is " +
                     "confirmed outside the baseline reduces demand (DEC-06)" };
  }

  /* ---------------- one priced candidate ---------------- */

  function finalise(inp, sku, riskPct) {
    var rows = demandRows(inp, sku);
    var s = summarise(rows);
    var byModel = totalsByModel(rows);
    var cert = certificationResult(rows);
    var conditional = sum(inp.extra_demand
      .filter(function (e) { return (e.unit || "UNIT") === "UNIT"; })
      .map(function (e) { return Number(e.qty || 0); }));
    var ledger = reuseLedger(inp, rows);
    var reuse = ledger.deduction;
    var pct = (riskPct === null || riskPct === undefined) ? inp.risk_reserve_pct : riskPct;
    pct = (pct === null || pct === undefined) ? 0.0 : pct;
    for (var i = 0; i < byModel.variants.length; i++) {
      var v = byModel.variants[i];
      v.conditional_increment = conditional;
      v.confirmed_reuse_adjustment = reuse;
      v.risk_reserve = (v.TOTAL + reuse) * pct;
      v.recommended_total = v.TOTAL + conditional + reuse + v.risk_reserve;
    }
    var vals = byModel.variants.map(function (x) { return x.recommended_total; });
    if (!vals.length) { vals = [0.0]; }
    var exact = byModel.variants.length === 1;
    var first = byModel.variants[0];
    var pcba = inp.extra_demand.filter(function (e) { return e.unit === "PCBA"; })
      .map(function (e) { return { qty: Number(e.qty || 0), label: e.label || "" }; });
    var certTotal = cert.present ? cert.certification_demand_total : 0.0;
    return {
      sku_qty: sku, single_value: exact,
      base_demand: exact ? first.TOTAL : null,
      base_demand_band: byModel.band, totals_by_model: byModel,
      fvt_total: exact ? first.FVT : null, sit_total: exact ? first.SIT : null,
      certification_demand: certTotal,
      non_certification_demand: exact ? (first.TOTAL - certTotal) : null,
      certification: cert, conditional_increment: conditional,
      confirmed_reuse_adjustment: reuse,
      reuse_summary: {
        requested_reuse_quantity: ledger.requested_reuse_quantity,
        adopted_reuse_quantity: ledger.adopted_reuse_quantity,
        rejected_or_deferred_quantity: ledger.rejected_or_deferred_quantity,
        adoption_reason: ledger.adopted_reuse_quantity
          ? "proven ADDITIONAL_CONFIRMED_REUSE, unit-denominated, confirmed outside the baseline" : null,
        non_adoption_reason: ledger.rejected_or_deferred_quantity
          ? "not proven, not unit-denominated, already embedded, potential only, or an unknown overlap" : null
      },
      potential_reuse_display_only: Number(inp.potential_reuse || 0),
      risk_reserve: exact ? first.risk_reserve : null,
      recommended_total: exact ? first.recommended_total : null,
      recommended_total_band: { min: Math.min.apply(null, vals), max: Math.max.apply(null, vals),
                                exact: exact },
      by_category: s.by_category, by_function: s.by_function,
      unresolved_functions: s.unresolved_functions, reuse_ledger: ledger,
      pcba_lines_not_summed: pcba, rounding: "NONE (D-01)", rows: rows
    };
  }

  /* ---------------- analysis ---------------- */

  function dedupeOris(oris) {
    var seen = {}, out = [];
    for (var i = 0; i < oris.length; i++) {
      var o = oris[i];
      var subj = o.factors || o.function_id || o.tie_set || o.detail || o.index;
      var key = JSON.stringify([o.kind, subj === undefined ? null : subj,
                                o.phase || "", o.sku_qty === undefined ? "" : o.sku_qty]);
      if (seen[key] !== undefined) {
        var tgt = out[seen[key]];
        if (o.scenario_id && (tgt.scenario_ids || []).indexOf(o.scenario_id) < 0) {
          tgt.scenario_ids = tgt.scenario_ids || [];
          tgt.scenario_ids.push(o.scenario_id);
        }
        continue;
      }
      seen[key] = out.length;
      out.push(o);
    }
    for (var k = 0; k < out.length; k++) {
      if (out[k].scenario_ids) { delete out[k].scenario_id; }
    }
    return out;
  }

  function j33EvidenceBlock() {
    var j = P.j33_investigation;
    return { source_cell: j.cell, evidence_role: BREAKDOWN, disposition: j.disposition,
             attached_to_function: "F_RF_CERTIFICATION",
             declared_reference_scenario: j.declared_reference_scenario,
             reference_total_under_readings: j.reference_total_under_readings,
             bracket: j.bracket,
             explains_main_table_per_sku_quantity: j.findings.explains_main_table_quantity,
             explains_appendix_total: j.findings.explains_appendix_total,
             antenna_wlan_are: j.findings.antenna_and_wlan_are,
             already_inside_main_table_rate: j.findings.already_inside_main_table_rate,
             double_count_risk_if_added: j.findings.double_count_risk_if_added,
             added_to_certification_result: false,
             mvp_requires_antenna_wlan_input_now: j.mvp_requires_antenna_wlan_input_now,
             raw_text: j.raw_text, owner_review_required: true };
  }

  function analyse(inp) {
    inp.normalise();
    var scenarios = waveScenarios(inp), oris = [], blocked = [];
    for (var i = 0; i < scenarios.length; i++) {
      var s = scenarios[i];
      s.match = matchSku(s.counts);
      s.candidates_priced = candidatesToPrice(s.match);
      s.results = s.candidates_priced.map(function (sku) { return finalise(inp, sku); });
      var fac = inp.factors(), wr = [];
      for (var d = 0; d < DIMS.length; d++) { wr.push(fac[DIMS[d]].waveReport()); }
      s.wave_report = wr;
      if (s.scope === "CURRENT_WAVE" && (s.unknown_factors || []).length) {
        oris.push({ kind: "WAVE_ASSIGNMENT_UNKNOWN", scenario_id: s.scenario_id,
                    factors: s.unknown_factors,
                    why: "the wave of these specs is explicitly marked UNKNOWN; CURRENT_WAVE " +
                         "is therefore reported as several scenarios. The engine will not " +
                         "decide it (DEC-04)." });
      }
      if (s.scope === "CURRENT_WAVE" && (s.untagged_factors || []).length) {
        oris.push({ kind: "WAVE_ASSIGNMENT_NOT_PROVIDED", scenario_id: s.scenario_id,
                    factors: s.untagged_factors,
                    why: "these Factors have more than one spec but nothing says which wave " +
                         "each spec belongs to. They are counted as CURRENT_WAVE by default, " +
                         "so CURRENT_WAVE equals FULL PROJECT for now. The Agent will not " +
                         "infer a second wave (DEC-04) - confirm the wave or accept this reading." });
      }
      if (s.match.state === "RANGE") {
        oris.push({ kind: "SKU_TIE_NOT_RESOLVABLE", scenario_id: s.scenario_id,
                    tie_set: s.match.tie_set,
                    why: s.match.tie_set[0] + " SKU and " + s.match.tie_set[s.match.tie_set.length - 1] +
                         " SKU cannot be separated by the current SKU Definition - ORI-04 stays " +
                         "open. Every certification demand is computed for each of them, so the " +
                         "range is SKU_NOT_ESTABLISHED, not a Certification model conflict." });
      }
      if (s.match.state === "OUT_OF_DOMAIN") {
        oris.push({ kind: "OUT_OF_DOMAIN_INPUT", scenario_id: s.scenario_id,
                    detail: s.match.out_of_domain,
                    why: "input exceeds the supported SKU Definition domain - ORI-13" });
      }
      for (var r = 0; r < s.results.length; r++) {
        var rl = s.results[r].reuse_ledger.owner_review_items;
        for (var q = 0; q < rl.length; q++) {
          var copy = {}; for (var kk in rl[q]) { copy[kk] = rl[q][kk]; }
          copy.scenario_id = s.scenario_id; copy.sku_qty = s.results[r].sku_qty;
          oris.push(copy);
        }
      }
    }
    var seenCell = {};
    for (var a = 0; a < scenarios.length; a++) {
      for (var b = 0; b < scenarios[a].results.length; b++) {
        var mm = scenarios[a].results[b].certification.mismatched_cells || [];
        for (var c2 = 0; c2 < mm.length; c2++) {
          var k2 = mm[c2].function_id + "|" + mm[c2].phase;
          if (seenCell[k2]) { continue; }
          seenCell[k2] = 1;
          oris.push({ kind: "CERTIFICATION_SOURCE_VALIDATION_MISMATCH",
                      function_id: mm[c2].function_id, phase: mm[c2].phase,
                      main_table_per_sku_quantity: mm[c2].main_table_per_sku_quantity,
                      main_table_derived_total: mm[c2].main_table_derived_total,
                      adopted_total: mm[c2].adopted_total,
                      appendix_total: mm[c2].appendix_total,
                      delta: mm[c2].delta,
                      main_table_row: mm[c2].main_table_row, appendix_row: mm[c2].appendix_row,
                      blocking_level: "BLOCKS_FORMALIZATION", blocks_manual_mvp: false,
                      why: "the Appendix total - which DEC-10 adopts - does not equal the Main " +
                           "Table per-SKU quantity x SKU count. The engine uses the Appendix " +
                           "total, keeps the Main Table derivation as audit evidence and " +
                           "reports the difference instead of editing the source. The result " +
                           "stays a single value: this is a source-data question, not a " +
                           "competing model, and the two are never added." });
        }
      }
    }
    var anyMismatch = false;
    for (var a2 = 0; a2 < scenarios.length; a2++) {
      for (var b2 = 0; b2 < scenarios[a2].results.length; b2++) {
        var cv = scenarios[a2].results[b2].certification;
        if (cv.present && cv.main_table_audit && cv.main_table_audit.mismatch) { anyMismatch = true; }
      }
    }
    if (anyMismatch) {
      oris.push({ kind: "CERTIFICATION_APPENDIX_VALIDATION_INCOMPLETE",
                  blocking_level: "BLOCKS_FORMALIZATION", blocks_manual_mvp: false,
                  why: "the Main Table x SKU relationship holds for part of the Certification " +
                       "grid only, so ORI-02 is PARTIALLY_RESOLVED and the rule pack cannot be " +
                       "finalised. DEC-10 decides WHICH column is adopted; it does not explain " +
                       "why the two columns disagree, so the difference stays registered for " +
                       "the Owner." });
    }
    if (P.j33_investigation.disposition === "DECLARED_NOT_GENERALIZED") {
      oris.push({ kind: "CERTIFICATION_BREAKDOWN_EVIDENCE_NOT_GENERALIZED", source_cell: "J33",
                  blocking_level: "ADVISORY", blocks_manual_mvp: false,
                  why: "J33 explains the RF Certification composition for one declared antenna " +
                       "x WLAN combination and cannot be reproduced from the workbook. It is " +
                       "kept as explanatory evidence, is never added to the adopted " +
                       "Certification value, and does not oblige the MVP to collect antenna / " +
                       "WLAN inputs today." });
    }
    for (var x = 0; x < scenarios.length; x++) {
      if (scenarios[x].match.state === "OUT_OF_DOMAIN") {
        blocked.push({ scenario_id: scenarios[x].scenario_id, reason: "OUT_OF_DOMAIN_INPUT",
                       explanation: "the input is outside the SKU Definition domain covered by " +
                                    "the rule pack, so no demand is published for this " +
                                    "scenario rather than extrapolating one." });
      }
    }
    var byKind = {};
    for (var y = 0; y < oris.length; y++) { byKind[oris[y].kind] = (byKind[oris[y].kind] || 0) + 1; }
    var summary = { total_items: oris.length, by_kind: byKind,
                    blocking_execution: oris.filter(function (o2) {
                      return o2.blocking_level === "BLOCKS_EXECUTION"; }).length,
                    blocks_manual_mvp: oris.some(function (o3) { return o3.blocks_manual_mvp; }),
                    note: "Owner Review Items inform the Owner; they do not stop the manual " +
                          "MVP unless blocks_manual_mvp is true (task section 25 test 22/23)." };
    return { input: inp, scenarios: scenarios,
             unresolved_comments_excluded: UNRESOLVED_COMMENTS,
             j33_evidence: j33EvidenceBlock(), blocked_scenarios: blocked,
             owner_review_items: dedupeOris(oris), owner_review_summary: summary,
             status: "DRAFT_UNCONFIRMED_BY_OWNER" };
  }

  function serialise(result, analysisId, displayPrecision) {
    if (displayPrecision === undefined) { displayPrecision = 2; }
    var KEYS = ["sku_qty", "single_value", "base_demand", "fvt_total", "sit_total",
                "certification_demand", "non_certification_demand", "certification",
                "risk_reserve", "recommended_total", "recommended_total_band",
                "conditional_increment", "confirmed_reuse_adjustment", "reuse_summary",
                "potential_reuse_display_only", "totals_by_model", "by_category",
                "by_function", "unresolved_functions", "reuse_ledger",
                "pcba_lines_not_summed", "rounding", "rows"];
    var scenarios = [];
    for (var i = 0; i < result.scenarios.length; i++) {
      var s = result.scenarios[i], results = [];
      for (var j = 0; j < s.results.length; j++) {
        var r = s.results[j], o = {};
        for (var k = 0; k < KEYS.length; k++) { o[KEYS[k]] = r[KEYS[k]]; }
        results.push(o);
      }
      scenarios.push({ scenario_id: s.scenario_id, scope: s.scope, wave_basis: s.wave_basis,
                       unknown_factors: s.unknown_factors || [],
                       untagged_factors: s.untagged_factors || [],
                       excluded_specs: s.excluded_specs || [],
                       truncated: !!s.truncated, identical_to_full_project: !!s.identical_to_full_project,
                       counts: s.counts, wave_report: s.wave_report, match: s.match,
                       candidates_priced: s.candidates_priced, results: results });
    }
    var csvRows = 0;
    for (var c = 0; c < scenarios.length; c++) {
      if (scenarios[c].results.length) {
        csvRows += scenarios[c].results.length * (scenarios[c].results[0].rows.length + 1);
      }
    }
    return {
      schema_version: "4.0", analysis_id: analysisId === undefined ? null : analysisId,
      baseline_id: P.baseline_id, rule_pack_version: P.pack_version,
      quantity_model_version: P.quantity_model_version,
      engine_version: ENGINE_NAME + "/" + ENGINE_VERSION,
      generated_at_utc: result.generated_at_utc || null,
      status: result.status,
      owner_decision: P.owner_decision,
      policy: { rounding: "NONE (D-01)", display_precision: displayPrecision,
                display_precision_modifies_values: false, comparison_tolerance: TOL,
                potential_reuse: "DISPLAY_ONLY", pcba_units: "NEVER_SUMMED_WITH_UNIT",
                product_names: "NOT_A_RULE",
                conflicting_evidence: "RETAINED_SEPARATELY_NOT_MERGED",
                panel_annotation_d2_h2: "UNRESOLVED_COMMENT_EXCLUDED",
                certification_model: "APPENDIX_ADOPTED_TOTAL (DEC-10)",
                certification_adopted_value_source: ADOPTED_SOURCE,
                certification_adopted_value_role: ADOPTED,
                certification_main_table_role: AUDIT,
                certification_main_derived_added_to_total: false,
                certification_main_table_and_appendix_added_together: false,
                certification_j33_role: BREAKDOWN,
                certification_j33_added_to_result: false,
                certification_global_phase_ratio: null,
                certification_range_reason_allowed: RANGE_REASON_SKU,
                certification_user_override_scope: "THIS_ANALYSIS_ONLY",
                mepa_hw_pa: "PER_PHASE_FIXED candidate, temporary pending Owner (ORI-10)" },
      unresolved_comments_excluded: result.unresolved_comments_excluded,
      j33_evidence: result.j33_evidence, scenarios: scenarios,
      owner_review_items: result.owner_review_items,
      owner_review_summary: result.owner_review_summary,
      export: { csv_rows: csvRows, full_precision_present: true,
                display_precision: displayPrecision,
                range_collapsed_to_single_value_on_export: false,
                certification_adopted_value_source: ADOPTED_SOURCE,
                main_table_audit_exported_for_review: true }
    };
  }

  function inputSnapshot(inp) {
    var fac = inp.factors(), kf = {};
    for (var d = 0; d < DIMS.length; d++) {
      var n = DIMS[d], f = fac[n];
      kf[n] = { name: n, file_value: f.file_value, user_value: f.user_value,
                user_edited: f.user_edited, effective: f.effective(),
                value_source: f.source(), user_status: f.statusUser() };
    }
    var declared = {}, specs = [];
    for (var d2 = 0; d2 < DIMS.length; d2++) {
      var sp = fac[DIMS[d2]].specs;
      for (var i = 0; i < sp.length; i++) {
        declared[sp[i].wave_source] = 1;
        specs.push({ factor: DIMS[d2], spec_index: i + 1, spec_label: sp[i].label,
                     wave: sp[i].wave, wave_source: sp[i].wave_source });
      }
    }
    var overrides = [];
    var co = inp.certification_override || {};
    for (var fid in co) { for (var ph in co[fid]) {
      overrides.push({ function_id: fid, phase: ph, qty: co[fid][ph] }); } }
    return { schema_version: "4.0", project_name: inp.project_name,
             project_type: inp.project_type, odm: inp.odm, phase_scope: inp.phase_scope,
             key_factors: kf,
             wave_assignment: { declared_by: (function () {
                                  var ks = Object.keys(declared).sort();
                                  return ks.length ? ks : ["NOT_PROVIDED"];
                                })(), specs: specs },
             certification_input: { mode: (overrides.length ? "USER_OVERRIDE_FOR_MISMATCH_CELLS"
                                                            : "SYSTEM_APPENDIX_ADOPTED"),
                                    override_scope: "THIS_ANALYSIS_ONLY",
                                    overrides: overrides },
             reuse_items: inp.reuse_items, additional_demand: inp.extra_demand,
             risk_reserve: { percent: inp.risk_reserve_pct },
             panel_annotation_d2_h2: "UNRESOLVED_COMMENT_EXCLUDED" };
  }

  global.NRE = {
    ENGINE_NAME: ENGINE_NAME, ENGINE_VERSION: ENGINE_VERSION, TOL: TOL,
    DIMS: DIMS, PHASES: PHASES, SKU_RANGE: SKU_RANGE,
    approx: approx, Spec: Spec, KeyFactor: KeyFactor, AnalysisInput: AnalysisInput,
    fromDocument: function (doc) { return AnalysisInput.fromDocument(doc); },
    waveScenarios: waveScenarios, matchSku: matchSku, candidatesToPrice: candidatesToPrice,
    demandRows: demandRows, certificationResult: certificationResult,
    totalsByModel: totalsByModel, reuseLedger: reuseLedger, finalise: finalise,
    analyse: analyse, serialise: serialise, inputSnapshot: inputSnapshot,
    definitions: definitions, domainBounds: domainBounds
  };
})(typeof window !== "undefined" ? window : globalThis);
